insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_art2_v1'
from (values
('117.203.b.1.A',2,'An eighth grader paints a still life of fruit set on a table in front of him. The source of his idea is:','["direct observation", "a printed answer key", "a random guess", "a memorized formula"]'::jsonb,0,'Painting what you see set up in front of you is direct observation.','original'),
('117.203.b.1.A',3,'Which of these is an imagination-based source for an artwork?','["tracing a leaf", "picturing a city that floats in the clouds", "copying a store sign", "measuring a real desk"]'::jsonb,1,'Imagination sources come from invented ideas, not from real objects.','original'),
('117.203.b.1.B',3,'In a drawing, a boundary that encloses a flat two-dimensional area is called a:','["space", "form", "shape", "texture"]'::jsonb,2,'Shape is flat and two-dimensional; form is three-dimensional.','original'),
('117.203.b.1.B',2,'A sculpture that has height, width and depth shows the element of:','["line", "rhythm", "pattern", "form"]'::jsonb,3,'Form is three-dimensional.','original'),
('117.203.b.1.C',3,'A painting where the left and right halves look equally weighted shows a feeling of:','["balance", "emphasis", "contrast", "movement"]'::jsonb,0,'Balance is the even distribution of visual weight.','original'),
('117.203.b.1.C',3,'An artist leads the viewer''s eye across a canvas using a curving road. She is using the principle of:','["unity", "movement", "proportion", "scale"]'::jsonb,1,'Movement guides the eye through the work.','original'),
('117.203.b.1.D',3,'A work whose meaning is clear to many viewers because of its symbols has strong:','["shipping cost", "paper weight", "meaning in its expressive content", "frame size"]'::jsonb,2,'Meaning is carried by the artwork''s expressive content.','original'),
('117.203.b.1.D',3,'An artist re-uses a famous pose in a new work to comment on today''s world. This is called:','["registration", "calibration", "erasure", "appropriation"]'::jsonb,3,'Appropriation borrows existing imagery and gives it new meaning.','original'),
('117.203.b.2.A',3,'A student combines a memory of her grandmother''s kitchen with her own invented patterns in a painting. This work is:','["an original artwork", "a kit project", "a photocopy", "a stolen image"]'::jsonb,0,'Original artworks come from the artist''s own ideas and sources.','original'),
('117.203.b.2.A',3,'Which would most likely be an original artwork based on personal experience?','["a copied cartoon", "a portrait series about a student''s move to a new town", "a traced logo", "a printed coloring page"]'::jsonb,1,'Personal experience is a source of original work.','original'),
('117.203.b.2.B',3,'A student tests three layouts, gets feedback and revises her poster. She is applying:','["a guess", "a shortcut", "the art-making process", "a rule of luck"]'::jsonb,2,'Planning, testing and revising make up the art-making process.','original'),
('117.203.b.2.B',2,'A designer makes a chair that fits small children. The goal is to generate a:','["copy of a chair", "hidden message", "random doodle", "design solution"]'::jsonb,3,'Design solves a stated problem with a planned result.','original'),
('117.203.b.2.C',3,'Which technique is used to build a sculpture by joining pieces together with glue or fasteners?','["assemblage", "contour drawing", "watercolor wash", "lithography"]'::jsonb,0,'Assemblage combines separate pieces into one work.','original'),
('117.203.b.2.C',2,'Pressing a carved, inked block onto paper to make copies is:','["photography", "printmaking", "weaving", "ceramics"]'::jsonb,1,'Printmaking transfers ink from a plate or block to paper.','original'),
('117.203.b.2.D',3,'A work that has entered the public domain can be:','["owned only by its first buyer", "used only by museums", "used by anyone without asking permission", "sold only once"]'::jsonb,2,'Public domain works are no longer protected by copyright.','original'),
('117.203.b.2.D',3,'Before using a photographer''s picture as the base of your collage, you should first check:','["the camera brand", "the frame color", "the paper size", "copyright status"]'::jsonb,3,'Copyright determines whether you may use the image.','original'),
('117.203.b.3.A',3,'A series of paintings made after a war shows the influence of ___ issues on art.','["historical", "grammar", "scheduling", "mathematical"]'::jsonb,0,'Historical events can shape the subjects artists choose.','original'),
('117.203.b.3.A',3,'Cultural traditions like festival masks show that art is shaped by:','["weather charts", "cultural beliefs", "bus maps", "price tags"]'::jsonb,1,'Masks reflect a culture''s beliefs and customs.','original'),
('117.203.b.3.B',3,'A statue honoring bravery still moves viewers today because of its:','["storage box", "date label", "universal theme", "paint brand"]'::jsonb,2,'Universal themes stay relevant across time.','original'),
('117.203.b.3.B',3,'To judge an artwork''s contemporary relevance, you ask how it connects to:','["the artist''s address", "last year''s weather", "the museum gift shop", "issues people care about now"]'::jsonb,3,'Relevance means the work speaks to present concerns.','original'),
('117.203.b.3.C',3,'A society''s folk songs and its woven textiles often share:','["similar motifs and stories", "the same size", "the same materials only", "the same price"]'::jsonb,0,'Arts of one culture reflect common values and imagery.','original'),
('117.203.b.3.C',3,'Comparing a poem and a painting from the same era can reveal:','["the type of frame", "shared ideas of that time", "the cost of paint", "the weight of the paper"]'::jsonb,1,'Different arts of one period often express shared ideas.','original'),
('117.203.b.3.D',2,'Which job is a design career?','["dentist", "farmer", "graphic designer", "lifeguard"]'::jsonb,2,'Graphic designers create visual communication.','original'),
('117.203.b.3.D',2,'Someone who paints for fun on weekends has an:','["school grade", "unpaid tax", "legal case", "avocational interest"]'::jsonb,3,'Avocational means pursued as a hobby.','original'),
('117.203.b.4.A',3,'A student writes about why she chose cool colors for her group''s mural. This response addresses the work''s:','["purpose", "shelf life", "postage", "insurance"]'::jsonb,0,'Responses explain purpose, ideas and choices.','original'),
('117.203.b.4.A',2,'Which sentence best uses art vocabulary in a written response?','["It was good.", "The artist used strong contrast to create a focal point.", "It was big.", "I just liked it."]'::jsonb,1,'Precise terms like contrast and focal point show understanding.','original'),
('117.203.b.4.B',3,'After describing an artwork, the next step of many critiques is to:','["sell it", "hide it", "analyze how it was made", "throw it away"]'::jsonb,2,'Critique steps move from describing to analyzing to interpreting to judging.','original'),
('117.203.b.4.B',3,'In critique, deciding how successful the work is, using reasons, is called:','["framing", "printing", "measuring", "judging"]'::jsonb,3,'Judging evaluates the artwork with evidence.','original'),
('117.203.b.4.C',2,'What best shows progress in a portfolio?','["early sketches next to later finished work", "unrelated flyers", "blank pages", "only one piece"]'::jsonb,0,'A portfolio shows growth over time.','original'),
('117.203.b.4.C',2,'A student chooses her best pieces for her portfolio. This is called:','["hiding drafts", "selecting work to share", "grading peers", "erasing mistakes"]'::jsonb,1,'A portfolio is a purposeful selection of work.','original'),
('117.203.b.4.D',2,'Visiting a local gallery lets students study original artworks:','["only on a screen", "only in books", "outside the classroom", "only on tests"]'::jsonb,2,'Venues outside school offer first-hand experience.','original'),
('117.203.b.4.E',2,'Good exhibition etiquette at a museum includes:','["picking up the sculptures", "leaning on the display", "running to the exit", "staying behind the line and using a quiet voice"]'::jsonb,3,'Etiquette protects the art and respects other visitors.','original'),
('117.203.b.4.D',3,'Which is the best reason to see an original painting in a gallery instead of a printed copy?','["you can notice its real size, surface and brushwork", "it is always smaller", "it is always cheaper", "it has no colors"]'::jsonb,0,'Originals reveal scale, texture and technique that reproductions hide.','original'),
('117.203.b.4.E',3,'When your class artwork is shown in the school hallway, proper display practice is to:','["fold it to fit", "add a title card with the artist''s name and mount it neatly", "cover it with other papers", "leave it loose on the floor"]'::jsonb,1,'Careful presentation is part of exhibition etiquette.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
